(function(){
  var NIV={app:1,vivo:2,presencial:3}, NIVr={1:"app",2:"vivo",3:"presencial"};
  function norm(s){ return String(s==null?"":s).normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase().replace(/\s+/g," ").trim(); }
  var _byNom=null;
  function _index(){ if(_byNom)return; _byNom={}; (window.SOCC_MOD.ejercicios||[]).forEach(function(e){ _byNom[norm(e.nombre)]=e; }); }
  // Busca el ejercicio de modalidad por nombre (match normalizado + aproximado)
  window.sccFindModalidad=function(nombre){ _index(); var k=norm(nombre); if(_byNom[k])return _byNom[k]; var keys=Object.keys(_byNom); for(var i=0;i<keys.length;i++){ if(keys[i].indexOf(k)>=0 || k.indexOf(keys[i])>=0) return _byNom[keys[i]]; } return null; };
  window.sccNivel=function(m){ return NIV[m]||1; };
  // Motor puro: resuelve la modalidad efectiva de un ejercicio para un perfil
  window.resolverModalidad=function(ej, perfil, fechaSesion){
    perfil=perfil||{}; var MODS=window.SOCC_MOD.modificadores_perfil||[];
    var base=NIV[(ej&&ej.modalidad_base)||"app"]; var cand=[base], estado_sp=null, motivos=[], positivo=false;
    var flags={}, zonas={}; (ej&&ej.flags||[]).forEach(function(f){flags[f]=1;}); (ej&&ej.zonas||[]).forEach(function(z){zonas[z]=1;});
    var F = fechaSesion ? new Date(fechaSesion) : new Date();
    MODS.forEach(function(m){
      var mid=m.id; if(mid==="avanzado_verificado") return;
      var activo=false;
      if(mid==="principiante"){ if(perfil.principiante && perfil.fecha_inicio){ var d=Math.floor((F-new Date(perfil.fecha_inicio))/86400000); activo = d <= (m.semanas_activo||4)*7; } }
      else if(mid==="osteoporosis_flexion"){ activo=!!perfil.osteoporosis; }
      else if(mid==="dolor_zona"){ activo=true; }
      else { activo=!!perfil[mid]; }
      if(!activo) return;
      var ap=m.aplica_si||{}, ok=true;
      if(ap.flags_alguno){ ok=ok && ap.flags_alguno.some(function(f){return flags[f];}); }
      if(ap.flags_no_incluye){ ok=ok && !ap.flags_no_incluye.some(function(f){return flags[f];}); }
      if(ap.zona_en_perfil){ ok=ok && (perfil.dolor_zonas||[]).some(function(z){return zonas[z];}); }
      if(!ok) return;
      positivo=true; motivos.push(m.mensaje); var delta=m.delta;
      if(delta==="evitar"){ if(estado_sp!=="bloqueado") estado_sp="evitar"; }
      else if(delta==="bloqueado"){ estado_sp="bloqueado"; }
      else if(delta==="presencial"){ cand.push(3); }
      else if(typeof delta==="number"){ cand.push(base+delta); }
      if(m.minimo){ cand.push(NIV[m.minimo]); }
    });
    var nivel_final=Math.max.apply(null,cand); var consultar=nivel_final>3; if(consultar) nivel_final=3;
    if(!positivo && perfil.avanzado_verificado){
      var av=MODS.filter(function(m){return m.id==="avanzado_verificado";})[0];
      if(av){ var req=(av.requiere_condiciones||[]).every(function(c){return !!perfil[c];}); var noexcl=!(av.excluye_flags||[]).some(function(f){return flags[f];}); if(req&&noexcl){ nivel_final=Math.max(1,nivel_final-1); motivos.push(av.mensaje); } }
    }
    var apto=(nivel_final<=NIV[perfil.modalidad_servicio||"app"]) && (estado_sp===null);
    var estado;
    if(estado_sp==="bloqueado") estado="bloqueado";
    else if(estado_sp==="evitar") estado="evitar";
    else estado=(consultar||nivel_final>base||!apto)?"advertencia":"ok";
    var mef = (estado_sp==="evitar"||estado_sp==="bloqueado") ? estado_sp : NIVr[nivel_final];
    return { modalidad_efectiva:mef, estado:estado, apto:apto, motivos:motivos };
  };
  // Badge visual por estado
  window.sccBadge=function(estado){ return {ok:"🟢",advertencia:"🟡",evitar:"🟠",bloqueado:"🔴"}[estado]||""; };
})();
